#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <algorithm>

using namespace std;

const int INF = 1000000000;

int N, M;
int capacity[2002][2002];
vector<int> graph[2002];
bool visited[2002];
int parent[2002];

int directions[][2] = { {1,0}, {0,1}, {-1,0}, {0,-1} };

int augment(int u) {
    if (u == 1) return INF;
    visited[u] = true;
    for (size_t i = 0; i < graph[u].size(); ++i) {
        int v = graph[u][i];
        if (!visited[v] && capacity[u][v] > 0) {
            int flow = augment(v);
            if (flow > 0) {
                parent[v] = u;
                return min(flow, capacity[u][v]);
            }
        }
    }
    return 0;
}

int maxFlow() {
    int totalFlow = 0;
    while (true) {
        memset(visited, false, sizeof(visited));
        int flow = augment(0);
        if (flow == 0) break;
        totalFlow += flow;
        int v = 1;
        while (v != 0) {
            int u = parent[v];
            capacity[u][v] -= flow;
            capacity[v][u] += flow;
            v = u;
        }
    }
    return totalFlow;
}

int main() {
    ios::sync_with_stdio(false);
    int gridSize, timeLimit;
    cin >> gridSize >> timeLimit;

    for (int i = 0; i < 2 * gridSize * gridSize + 2; ++i) {
        graph[i].clear();
        for (int j = 0; j < 2 * gridSize * gridSize + 2; ++j)
            capacity[i][j] = 0;
    }

    vector<string> sciLabs(gridSize), capLabs(gridSize);
    int vert[gridSize][gridSize][2];
    int malfunctionIndex;

    N = 2;
    for (int i = 0; i < gridSize; ++i) {
        cin >> sciLabs[i];
        for (int j = 0; j < gridSize; ++j) {
            if (sciLabs[i][j] >= '1' && sciLabs[i][j] <= '9') {
                capacity[0][N] = sciLabs[i][j] - '0';
                graph[0].push_back(N);
                graph[N].push_back(0);
                vert[i][j][0] = N++;
            } else if (sciLabs[i][j] == 'Z') {
                malfunctionIndex = 100 * i + j;
                sciLabs[i][j] = 'Y';
            }
        }
    }

    M = N;
    for (int i = 0; i < gridSize; ++i) {
        cin >> capLabs[i];
        for (int j = 0; j < gridSize; ++j) {
            if (capLabs[i][j] >= '1' && capLabs[i][j] <= '9') {
                capacity[M][1] = capLabs[i][j] - '0';
                graph[M].push_back(1);
                vert[i][j][1] = M++;
            }
        }
    }

    int die[gridSize][gridSize];
    for (int i = 0; i < gridSize; ++i)
        for (int j = 0; j < gridSize; ++j)
            die[i][j] = timeLimit + 1;
    die[malfunctionIndex / 100][malfunctionIndex % 100] = 0;

    queue<int> q;
    q.push(malfunctionIndex);
    while (!q.empty()) {
        int x = q.front(); q.pop();
        int y = x % 100; x /= 100;
        for (int d = 0; d < 4; ++d) {
            int nx = x + directions[d][0];
            int ny = y + directions[d][1];
            if (nx >= 0 && nx < gridSize && ny >= 0 && ny < gridSize && sciLabs[nx][ny] != 'Y' && die[nx][ny] > die[x][y] + 1) {
                die[nx][ny] = die[x][y] + 1;
                q.push(100 * nx + ny);
            }
        }
    }

    int reach[gridSize][gridSize];
    for (int i = 0; i < gridSize; ++i)
        for (int j = 0; j < gridSize; ++j)
            reach[i][j] = timeLimit + 1;

    for (int i = 0; i < gridSize; ++i) {
        for (int j = 0; j < gridSize; ++j) {
            if (sciLabs[i][j] >= '1' && sciLabs[i][j] <= '9') {
                for (int x = 0; x < gridSize; ++x)
                    for (int y = 0; y < gridSize; ++y)
                        reach[x][y] = timeLimit + 1;
                reach[i][j] = 0;
                if (capLabs[i][j] >= '1' && capLabs[i][j] <= '9') {
                    capacity[vert[i][j][0]][vert[i][j][1]] = INF;
                    graph[vert[i][j][0]].push_back(vert[i][j][1]);
                    graph[vert[i][j][1]].push_back(vert[i][j][0]);
                }
                queue<int> q2;
                q2.push(100 * i + j);
                while (!q2.empty()) {
                    int x = q2.front(); q2.pop();
                    int y = x % 100; x /= 100;
                    for (int d = 0; d < 4; ++d) {
                        int nx = x + directions[d][0];
                        int ny = y + directions[d][1];
                        if (nx >= 0 && nx < gridSize && ny >= 0 && ny < gridSize && sciLabs[nx][ny] != 'Y' && reach[nx][ny] > reach[x][y] + 1) {
                            if (capLabs[nx][ny] >= '1' && capLabs[nx][ny] <= '9') {
                                if (reach[x][y] + 1 <= die[nx][ny]) {
                                    capacity[vert[i][j][0]][vert[nx][ny][1]] = INF;
                                    graph[vert[i][j][0]].push_back(vert[nx][ny][1]);
                                    graph[vert[nx][ny][1]].push_back(vert[i][j][0]);
                                }
                            }
                            if (reach[x][y] + 1 < die[nx][ny]) {
                                reach[nx][ny] = reach[x][y] + 1;
                                q2.push(100 * nx + ny);
                            }
                        }
                    }
                }
            }
        }
    }

    cout << maxFlow() << endl;
    return 0;
}
